  bundle.reviews.push(
    rv(IMG, "quality-accessible-media", "fail", "The item's only content is an informative image: a bitmap showing one line of text. The PDF has no text layer (PDFKit returns no page text; no fonts or text operators in the file) and the tagged Figure has no /Alt or /ActualText entry, so no text alternative exists for the informative image. The text became readable only through OCR. Scope: single page, single image; nothing else on the page.", [CON, MED]),
